"use strict";


function ordenNatural(a, b) { return String(a.puntoMedido || "").localeCompare(String(b.puntoMedido || ""), "es", { numeric: true, sensitivity: "base" }); }
async function exportarMonografiasJuntas(lista, etiqueta) {
  const { jsPDF } = window.jspdf; void jsPDF;
  if (!lista.length) return toast("No hay monografías para descargar.");
  let doc = null, i = 0;
  for (const m of lista) {
    i++;
    toast("Generando " + i + " de " + lista.length + "…");
    await new Promise((r) => setTimeout(r, 0));
    const imgs = await prepararImagenesMonografia(m);
    doc = construirMonografiaPdf(m, imgs, doc);
  }
  const hoy = new Date().toISOString().slice(0, 10);
  doc.save("monografias_" + (etiqueta || "todas").replace(/[^a-z0-9_-]+/gi, "_") + "_" + hoy + ".pdf");
  toast("PDF con " + lista.length + " monografía(s) generado");
}
function abrirDescargaTodasMonografias() {
  const proys = Array.from(new Set(state.monografias.map((m) => (m.nombreProyecto || "").trim()).filter(Boolean)));
  const ov = document.createElement("div");
  ov.className = "modal-overlay";
  ov.innerHTML = `<div class="modal" style="max-width:420px;">
    <h2>Descargar todas juntas</h2>
    <p class="muted">Un solo PDF, una monografía por página (o más si llevan fotos adicionales).</p>
    <label>Qué incluir</label>
    <select id="dtAlcance"><option value="">Todas (${state.monografias.length})</option>${proys.map((p) => `<option value="${escapeHtml(p)}">Solo proyecto: ${escapeHtml(p)}</option>`).join("")}</select>
    <label>Orden</label>
    <select id="dtOrden"><option value="punto">Por nombre de punto</option><option value="creacion">Por fecha de creación</option></select>
    <div class="modal-actions" style="display:flex; gap:8px; margin-top:12px;">
      <button class="btn btn-outline" id="dtCancelar" type="button" style="flex:1;">Cancelar</button>
      <button class="btn btn-accent" id="dtOk" type="button" style="flex:1;">Descargar</button>
    </div></div>`;
  document.body.appendChild(ov);
  ov.querySelector("#dtCancelar").addEventListener("click", () => ov.remove());
  ov.querySelector("#dtOk").addEventListener("click", async () => {
    const alc = ov.querySelector("#dtAlcance").value, ord = ov.querySelector("#dtOrden").value;
    let lista = state.monografias.filter((m) => !alc || (m.nombreProyecto || "").trim() === alc);
    lista = lista.slice().sort(ord === "punto" ? ordenNatural : (a, b) => new Date(a.creado) - new Date(b.creado));
    ov.remove();
    await exportarMonografiasJuntas(lista, alc || "todas");
  });
}
async function exportarMonografiaPdf(monografiaId) {
  const m = state.monografias.find((x) => x.id === monografiaId);
  if (!m) return;
  toast("Generando PDF…");
  const doc = construirMonografiaPdf(m, await prepararImagenesMonografia(m));
  doc.save("monografia_" + (m.puntoMedido || "punto").replace(/[^a-z0-9_-]+/gi, "_") + ".pdf");
  toast("PDF generado");
}

/* Construye el PDF de una monografía, replicando el layout de la plantilla
   de muestra: encabezado con logo cliente + título + logo propio, barra de
   proyecto, ficha del punto, tablas de coordenadas, croquis + panorámica
   lado a lado, descripción y firma de operador/revisó. Cada sección se omite
   si su módulo está desactivado. */
/* jsPDF exige que el formato declarado coincida con el de la imagen real, o
   falla silenciosamente dejando el recuadro vacío — se detecta desde el
   propio dataURL en vez de asumir un formato fijo. */
function formatoImagenJsPDF(dataUrl) {
  const m = /^data:image\/(png|jpe?g|webp)/i.exec(dataUrl || "");
  if (!m) return "JPEG";
  const t = m[1].toLowerCase();
  if (t === "png") return "PNG";
  if (t === "webp") return "WEBP";
  return "JPEG";
}

/* Réplica fiel del formato tipo de la empresa (monografía de PRs y monolitos):
   cuadrícula de líneas azul marino, título en 3 columnas (cliente/título/
   logo propio), barra de proyecto, fila Punto Medido + Ubicación, tabla
   combinada UTM+Geodésicas en una sola franja con encabezado azul sólido,
   croquis + vista panorámica lado a lado, descripción como líneas simples,
   y pie Datos operador / Revisó (la columna Revisó va centrada, sin
   etiquetas, igual que en la plantilla original). Todo dibujado a mano con
   rect/text en vez de autoTable, para calzar exactamente con la muestra.
   Cada bloque se omite si su módulo está desactivado. */
/* Fuente Carlito (recortada a los caracteres usados en español), embebida
   para que las monografías salgan con el mismo tipo de letra que la
   plantilla original de la empresa (Calibri) en vez de la Helvetica por
   defecto de jsPDF — Carlito es metricamente compatible con Calibri y de
   licencia libre (SIL OFL), por eso se usa como reemplazo fiel. Se registra
   en cada documento jsPDF nuevo (el VFS de fuentes vive por instancia). */
const FUENTE_CARLITO_REGULAR = "";
const FUENTE_CARLITO_BOLD = "";
function registrarFuenteMonografia(doc) {
  doc.addFileToVFS("Carlito-Regular.ttf", FUENTE_CARLITO_REGULAR);
  doc.addFont("Carlito-Regular.ttf", "Carlito", "normal");
  doc.addFileToVFS("Carlito-Bold.ttf", FUENTE_CARLITO_BOLD);
  doc.addFont("Carlito-Bold.ttf", "Carlito", "bold");
}

/* Decide qué fuente usar en el PDF según lo elegido en Configuración, y la
   registra en el documento si hace falta. Devuelve el nombre de familia a
   pasar a doc.setFont(...). Si el usuario subió una fuente propia pero algo
   falla al registrarla (archivo corrupto, etc.), se cae de vuelta a Carlito
   en vez de romper la generación del PDF. */
function prepararFuentePdf(doc) {
  const cfg = state.config.fuenteMonografia || { tipo: "carlito" };
  if (cfg.tipo === "helvetica") return "helvetica";
  if (cfg.tipo === "times") return "times";
  if (cfg.tipo === "personalizada" && cfg.personalizadaRegular) {
    try {
      doc.addFileToVFS("FuentePersonalizada-Regular.ttf", cfg.personalizadaRegular);
      doc.addFont("FuentePersonalizada-Regular.ttf", "DocFuente", "normal");
      if (cfg.personalizadaBold) {
        doc.addFileToVFS("FuentePersonalizada-Bold.ttf", cfg.personalizadaBold);
        doc.addFont("FuentePersonalizada-Bold.ttf", "DocFuente", "bold");
      } else {
        // Sin negrita propia: se registra la misma regular bajo "bold" para
        // que doc.setFont(...,"bold") no falle — solo no se verá más gruesa.
        doc.addFont("FuentePersonalizada-Regular.ttf", "DocFuente", "bold");
      }
      return "DocFuente";
    } catch (e) {
      registrarFuenteMonografia(doc);
      return "Carlito";
    }
  }
  registrarFuenteMonografia(doc);
  return "Carlito";
}

const MONO_NAVY = [31, 58, 95];
const MONO_NEGRO = [20, 22, 21];
const MONO_GRIS = [90, 90, 90];

/* v0.1d — medidas (mm) de cada recuadro de imagen, compartidas por la vista de ajuste y el PDF */
function dimsMonografia(m) {
  const mod = m.modulos || {};
  const lado = (m.disposicionImg || "lado") === "lado" && mod.croquis && mod.panoramica;
  const wB = lado ? 95 : 190;
  const hB = Math.min(120, Math.max(30, Number(m.altoImagenes) || 56));
  const hE = Math.min(120, Math.max(30, Number(m.altoFotosExtra) || 60));
  return {
    lado, hB, hE,
    clienteLogo: [36, 16], logoEmpresa: [34, 16],
    croquisImg: [wB - 1, hB - 1], panoramicaImg: [wB - 1, hB - 1],
    extra: [94, hE - 1]
  };
}
function ajusteDe(m, clave, porDefecto) {
  return Object.assign({ modo: porDefecto || "llenar", zoom: 1, ox: 0, oy: 0, giro: 0 }, (m.ajustes || {})[clave] || {});
}
/* Pre-renderiza cada imagen a la proporción exacta de su recuadro (sin deformar). */
async function prepararImagenesMonografia(m) {
  const d = dimsMonografia(m), mod = m.modulos || {}, out = { extras: {} };
  const marca = state.config.marca || {};
  const hacer = async (url, dim, aj, png) => { try { return await renderizarImagenAjustada(url, dim[0], dim[1], aj, { png }); } catch (_) { return null; } };
  if (m.clienteLogo) out.clienteLogo = await hacer(m.clienteLogo, d.clienteLogo, ajusteDe(m, "clienteLogo", "ajustar"), true);
  if (marca.logoEmpresa) out.logoEmpresa = await hacer(marca.logoEmpresa, d.logoEmpresa, { modo: "ajustar" }, true);
  if (mod.croquis && m.croquisImg) out.croquisImg = await hacer(m.croquisImg, d.croquisImg, ajusteDe(m, "croquisImg"), false);
  if (mod.panoramica && m.panoramicaImg) out.panoramicaImg = await hacer(m.panoramicaImg, d.panoramicaImg, ajusteDe(m, "panoramicaImg"), false);
  if (mod.fotos) for (const f of (m.fotosExtra || [])) if (f.img) out.extras[f.id] = await hacer(f.img, d.extra, Object.assign({ modo: "llenar" }, f.aj || {}), false);
  return out;
}

function construirMonografiaPdf(m, imgs, docExistente) {
  imgs = imgs || { extras: {} };
  const { jsPDF } = window.jspdf;
  const doc = docExistente || new jsPDF();
  if (docExistente) doc.addPage();            // PDF combinado: cada monografía parte en página nueva
  const nombreFuente = docExistente ? docExistente.__nombreFuente : prepararFuentePdf(doc);
  doc.__nombreFuente = nombreFuente;
  const X0 = 10, W = 190;
  let y = 12;

  const marca = state.config.marca;

  function caja(x, w, h, relleno) {
    if (relleno) { doc.setFillColor(...MONO_NAVY); doc.rect(x, y, w, h, "F"); }
    doc.setDrawColor(...MONO_NAVY);
    doc.setLineWidth(0.3);
    doc.rect(x, y, w, h);
  }
  function txt(s, x, yy, opts) {
    opts = opts || {};
    doc.setFont(nombreFuente, opts.bold ? "bold" : "normal");
    doc.setFontSize(opts.size || 9);
    doc.setTextColor(...(opts.color || MONO_NEGRO));
    doc.text(s, x, yy, { align: opts.align || "left" });
  }

  // ---- Fila A: Cliente+logo | Título | Logo propio ----
  const hA = 26;
  const wCliente = 42, wLogo = 42, wTitulo = W - wCliente - wLogo;
  caja(X0, wCliente, hA);
  caja(X0 + wCliente, wTitulo, hA);
  caja(X0 + wCliente + wTitulo, wLogo, hA);
  txt("Cliente:", X0 + 2, y + 5, { size: 7.5 });
  if (imgs.clienteLogo) {
    try { doc.addImage(imgs.clienteLogo, "PNG", X0 + 3, y + 7, wCliente - 6, hA - 10, undefined, "FAST"); } catch (e) {}
  }
  txt(m.tituloDocumento || "Monografía de PRs y Monolitos", X0 + wCliente + wTitulo / 2, y + hA / 2 + 2, { bold: true, size: 15, align: "center", color: MONO_NEGRO });
  if (imgs.logoEmpresa) {
    try { doc.addImage(imgs.logoEmpresa, "PNG", X0 + wCliente + wTitulo + 4, y + 5, wLogo - 8, hA - 10, undefined, "FAST"); } catch (e) {}
  }
  y += hA;

  // ---- Fila B: barra de proyecto (sin relleno, solo borde) ----
  if (m.nombreProyecto) {
    const hB = 10;
    caja(X0, W, hB);
    // Título del proyecto centrado; si es muy largo, se reduce la letra hasta que quepa
    const tituloProy = m.nombreProyecto.toUpperCase();
    let szProy = 10.5;
    doc.setFont(nombreFuente, "bold");
    while (szProy > 6.5) { doc.setFontSize(szProy); if (doc.getTextWidth(tituloProy) <= W - 8) break; szProy -= 0.5; }
    txt(tituloProy, X0 + W / 2, y + hB / 2 + 2, { bold: true, size: szProy, align: "center" });
    y += hB;
  }

  // ---- Fila C: Punto medido | Ubicación ----
  const hC = 15;
  const wPunto = W * 0.62, wUbic = W - wPunto;
  caja(X0, wPunto, hC);
  caja(X0 + wPunto, wUbic, hC);
  txt("Punto medido:", X0 + 3, y + hC / 2 + 1.5, { size: 9 });
  txt(m.puntoMedido || "—", X0 + wPunto / 2 + 14, y + hC / 2 + 2, { bold: true, size: 15, align: "center" });
  const unir = (...a) => a.map((v) => (v || "").trim()).filter(Boolean).join(", ");
  const l1 = unir(m.ubicacion, m.localidad) || "—";
  const l2 = unir(m.comuna, m.region || m.provincia);
  const ajustar = (s, maxW, size) => { doc.setFont(nombreFuente, "normal"); let z = size; doc.setFontSize(z); while (z > 5.5 && doc.getTextWidth(s) > maxW) { z -= 0.5; doc.setFontSize(z); } return z; };
  txt("Ubicación:", X0 + wPunto + 3, y + 6, { size: 9 });
  const maxU = wUbic - 26 - 2;
  txt(l1, X0 + wPunto + 26, y + 6, { size: ajustar(l1, maxU, 9) });
  if (l2) txt(l2, X0 + wPunto + 26, y + 11.5, { size: ajustar(l2, maxU, 9) });
  y += hC;

  // ---- Coordenadas UTM / Geodésicas (combinadas en una franja) ----
  const utmOn = m.modulos.utm, geoOn = m.modulos.geodesicas;
  if (utmOn || geoOn) {
    const mitad = utmOn && geoOn;
    const wBloque = mitad ? W / 2 : W;

    // Encabezados de cada bloque
    const hEnc = 5.5;
    if (utmOn) {
      caja(X0, wBloque, hEnc);
      txt("Coordenadas UTM - " + [m.datumUTM, m.zonaUTM].filter(Boolean).join("- Zona "), X0 + 2, y + hEnc - 1.5, { bold: true, size: 8 });
    }
    if (geoOn) {
      const x = mitad ? X0 + wBloque : X0;
      caja(x, wBloque, hEnc);
      txt("Coordenadas Geodésicas - " + (m.datumGeodesico || ""), x + 2, y + hEnc - 1.5, { bold: true, size: 8 });
    }
    y += hEnc;

    // Línea de geoide / nota de formato
    const hNota = 4.5;
    if (utmOn) {
      caja(X0, wBloque, hNota);
      txt("Geoide: " + (m.geoide || "—"), X0 + 2, y + hNota - 1.2, { size: 7 });
    }
    if (geoOn) {
      const x = mitad ? X0 + wBloque : X0;
      caja(x, wBloque, hNota);
      const esGMS = /[°º'′"″]/.test(String(m.latitud || "") + String(m.longitud || ""));
      txt(esGMS ? "Coordenadas en grados, minutos y segundos" : "Coordenadas en grados decimales", x + 2, y + hNota - 1.2, { size: 7, color: MONO_GRIS });
    }
    y += hNota;

    // Encabezado azul de la tabla (4 sub-columnas por bloque)
    const hHead = 6.5;
    function subcolsUTM(x0, w0) { return [{ l: "Punto", w: w0 * 0.17 }, { l: "Norte(m)", w: w0 * 0.28 }, { l: "Este(m)", w: w0 * 0.28 }, { l: "Cota Ortométrica(m)", w: w0 * 0.27 }]; }
    function subcolsGEO(x0, w0) { return [{ l: "Punto", w: w0 * 0.17 }, { l: "Latitud (°)", w: w0 * 0.28 }, { l: "Longitud (°)", w: w0 * 0.28 }, { l: "Altura Elip(m)", w: w0 * 0.27 }]; }
    // Encoge el texto (hasta un mínimo) si no cabe en el ancho de la columna
    // — evita que encabezados largos como "Cota Ortométrica(m)" se corten.
    function sizeParaAncho(texto, anchoDisponible, bold) {
      let tam = 8;
      doc.setFont(nombreFuente, bold ? "bold" : "normal");
      doc.setFontSize(tam);
      while (tam > 5 && doc.getTextWidth(texto) > anchoDisponible) {
        tam -= 0.5;
        doc.setFontSize(tam);
      }
      return tam;
    }
    function filaCols(x0, w0, cols, valores, bold) {
      let cx = x0;
      cols.forEach((c, i) => {
        doc.setDrawColor(...MONO_NAVY); doc.setLineWidth(0.25);
        doc.rect(cx, y, c.w, bold ? hHead : 6);
        const tam = sizeParaAncho(valores[i], c.w - 2, bold);
        txt(valores[i], cx + c.w / 2, y + (bold ? hHead : 6) / 2 + 1.5, { bold, size: tam, align: "center", color: bold ? [255, 255, 255] : MONO_NEGRO });
        cx += c.w;
      });
    }
    if (utmOn) {
      doc.setFillColor(...MONO_NAVY); doc.rect(X0, y, wBloque, hHead, "F");
      filaCols(X0, wBloque, subcolsUTM(X0, wBloque), ["Punto", "Norte(m)", "Este(m)", "Cota Ortométrica(m)"], true);
    }
    if (geoOn) {
      const x = mitad ? X0 + wBloque : X0;
      doc.setFillColor(...MONO_NAVY); doc.rect(x, y, wBloque, hHead, "F");
      filaCols(x, wBloque, subcolsGEO(x, wBloque), ["Punto", "Latitud (°)", "Longitud (°)", "Altura Elip(m)"], true);
    }
    y += hHead;

    // Fila de datos
    if (utmOn) filaCols(X0, wBloque, subcolsUTM(X0, wBloque), [m.puntoMedido || "—", m.norte || "—", m.este || "—", m.cotaOrtometrica || "—"], false);
    if (geoOn) filaCols(mitad ? X0 + wBloque : X0, wBloque, subcolsGEO(X0, wBloque), [m.puntoMedido || "—", m.latitud || "—", m.longitud || "—", m.alturaElipsoidal || "—"], false);
    y += 6.5;
  }

  // ---- Croquis + Vista panorámica ----
  const croqOn = m.modulos.croquis, panoOn = m.modulos.panoramica;
  if (croqOn || panoOn) {
    const dm = dimsMonografia(m);
    const mitad = croqOn && panoOn && dm.lado;
    const wBloque = mitad ? W / 2 : W;
    const imgH = dm.hB;
    const bloques = [];
    if (croqOn) bloques.push({ titulo: "Croquis Ubicación", img: imgs.croquisImg });
    if (panoOn) bloques.push({ titulo: "Vista Panorámica", img: imgs.panoramicaImg });
    const filas = mitad ? [bloques] : bloques.map((b) => [b]);
    filas.forEach((fila) => {
      if (y + 6 + imgH > 282) { doc.addPage(); y = 14; }
      const hEnc = 5.5;
      fila.forEach((b, k) => { const x = X0 + k * wBloque; caja(x, wBloque, hEnc); txt(b.titulo, x + 2, y + hEnc - 1.5, { bold: true, size: 8 }); });
      y += hEnc;
      fila.forEach((b, k) => {
        const x = X0 + k * wBloque;
        caja(x, wBloque, imgH);
        if (b.img) { try { doc.addImage(b.img, "JPEG", x + 0.5, y + 0.5, wBloque - 1, imgH - 1, undefined, "FAST"); } catch (e) {} }
      });
      y += imgH;
    });
  }

  // ---- Descripción (líneas simples, sin viñetas, igual que la plantilla) ----
  if (m.modulos.descripcion) {
    if (y > 255) { doc.addPage(); y = 14; }
    const lineasTexto = (m.descripcion || "").split("\n").filter((l) => l.trim());
    if (m.equipoGNSS) lineasTexto.push("Equipo GNSS: " + m.equipoGNSS);
    if (m.tipoMedicion) lineasTexto.push("Tipo de Medición: " + m.tipoMedicion);
    const hDescTxt = Math.max(lineasTexto.length * 4.3 + 2, 6);
    const hEnc = 5.5;
    caja(X0, W, hEnc);
    txt("Descripción:", X0 + 2, y + hEnc - 1.5, { bold: true, size: 8.5 });
    y += hEnc;
    caja(X0, W, hDescTxt);
    let ly = y + 4;
    doc.setFont(nombreFuente, "normal"); doc.setFontSize(8.5); doc.setTextColor(...MONO_NEGRO);
    lineasTexto.forEach((l) => { doc.text(l, X0 + 2, ly); ly += 4.3; });
    y += hDescTxt;
  }

  // ---- Fotografías adicionales (2 por fila, con leyenda) ----
  if (m.modulos.fotos && (m.fotosExtra || []).length) {
    const dm = dimsMonografia(m);
    const fotos = m.fotosExtra.filter((f) => f.img);
    const wF = W / 2, hEnc = 5.5, hLey = 6;
    for (let i = 0; i < fotos.length; i += 2) {
      if (y + hEnc + dm.hE + hLey > 285) { doc.addPage(); y = 14; }
      if (i === 0) { caja(X0, W, hEnc); txt("Fotografías adicionales", X0 + 2, y + hEnc - 1.5, { bold: true, size: 8 }); y += hEnc; }
      [fotos[i], fotos[i + 1]].forEach((f, k) => {
        if (!f) return;
        const x = X0 + k * wF;
        caja(x, wF, dm.hE);
        const r = imgs.extras[f.id];
        if (r) { try { doc.addImage(r, "JPEG", x + 0.5, y + 0.5, wF - 1, dm.hE - 1, undefined, "FAST"); } catch (e) {} }
      });
      // leyendas bajo cada imagen
      y += dm.hE;
      [fotos[i], fotos[i + 1]].forEach((f, k) => {
        if (!f) return;
        const x = X0 + k * wF;
        caja(x, wF, hLey);
        txt(String(f.leyenda || "").slice(0, 70), x + 2, y + hLey - 1.8, { size: 8 });
      });
      y += hLey;
    }
  }

  // ---- Datos operador / Revisó ----
  if (m.modulos.firma) {
    if (y > 260) { doc.addPage(); y = 14; }
    const wMitad = W / 2;
    const hEnc = 6;
    caja(X0, wMitad, hEnc);
    caja(X0 + wMitad, wMitad, hEnc);
    txt("Datos operador", X0 + wMitad / 2, y + hEnc - 2, { bold: true, size: 9, align: "center" });
    txt("Revisó", X0 + wMitad + wMitad / 2, y + hEnc - 2, { bold: true, size: 9, align: "center" });
    y += hEnc;

    const filasIzq = ["Nombre: " + (m.operadorNombre || "—"), "Cargo: " + (m.operadorCargo || "—"), "Fecha Medición: " + (m.fechaMedicion ? fmtFechaCorta(m.fechaMedicion) : "—")];
    const filasDer = [m.revisoNombre || "—", m.fechaRevision ? fmtFechaCorta(m.fechaRevision) : ""].filter(Boolean);
    const hDatos = Math.max(filasIzq.length, 1) * 5 + 3;
    caja(X0, wMitad, hDatos);
    caja(X0 + wMitad, wMitad, hDatos);
    let ly = y + 5;
    filasIzq.forEach((l) => { txt(l, X0 + 2, ly, { size: 8.5 }); ly += 5; });
    ly = y + 5;
    filasDer.forEach((l) => { txt(l, X0 + wMitad + wMitad / 2, ly, { size: 8.5, align: "center" }); ly += 5; });
    y += hDatos;
  }

  return doc;
}
function fmtFechaCorta(isoDate) {
  if (!isoDate) return "—";
  const [a, m, d] = isoDate.split("-");
  return d + "-" + m + "-" + a;
}

function construirWorkbook(jornadaId) {
  const j = state.jornadas.find((x) => x.id === jornadaId);
  const levs = levantamientosDeJornada(jornadaId);
  if (!j) return null;

  const wb = XLSX.utils.book_new();

  const resumen = [
    ["Operador", j.operador || "—"],
    ["Fecha inicio", fmtFecha(j.fechaInicio)],
    ["Fecha término", j.fechaTermino ? fmtFecha(j.fechaTermino) : "—"],
    ["Horas trabajadas", j.horas != null ? j.horas.toFixed(2) : "—"],
    ["Ubicación inicio", fmtCoord(j.lat, j.lng)],
    ["N° de levantamientos", levs.length]
  ];
  const wsResumen = XLSX.utils.aoa_to_sheet(resumen);
  XLSX.utils.book_append_sheet(wb, wsResumen, "Resumen Jornada");

  levs.forEach((l, idx) => {
    const columnas = INSTRUMENTOS[l.instrumento].tipos[l.tipo].columnas;
    const headers = columnas.map((c) => c.label).concat(["Hora", "Latitud", "Longitud", "Origen Ubicación", "Tiene Foto"]);
    const rows = l.puntos.map((p) => {
      const row = columnas.map((c) => p.valores[c.key] ?? "");
      row.push(fmtHoraCorta(p.timestamp), p.lat ?? "", p.lng ?? "", fmtFuenteUbic(p.ubicFuente), p.foto ? "Sí (ver reporte PDF)" : "No");
      return row;
    });
    const ws = XLSX.utils.aoa_to_sheet([headers, ...rows]);
    const nombreHoja = (idx + 1) + "-" + l.tipoNombre.replace(/[\\/?*[\]:]/g, "").slice(0, 25);
    XLSX.utils.book_append_sheet(wb, ws, nombreHoja);
  });

  return wb;
}

async function exportarPdf(jornadaId) {
  const j = state.jornadas.find((x) => x.id === jornadaId);
  if (!j) return;
  toast("Generando PDF…");
  const doc = await construirPdfDoc(jornadaId);
  doc.save("terreno_" + j.fechaInicio.slice(0, 10) + ".pdf");
  toast("PDF generado");
}

async function construirPdfDoc(jornadaId) {
  const j = state.jornadas.find((x) => x.id === jornadaId);
  const levs = levantamientosDeJornada(jornadaId);
  if (!j) return null;

  const { jsPDF } = window.jspdf;
  const doc = new jsPDF();
  let y = 16;

  doc.setFontSize(16);
  doc.text("Reporte de Jornada de Terreno", 14, y); y += 8;
  doc.setFontSize(10);
  if (j.proyecto) { doc.text("Proyecto: " + j.proyecto, 14, y); y += 5; }
  if (j.operador) { doc.text("Operador: " + j.operador, 14, y); y += 5; }
  doc.text("Fecha inicio: " + fmtFecha(j.fechaInicio), 14, y); y += 5;
  doc.text("Fecha término: " + (j.fechaTermino ? fmtFecha(j.fechaTermino) : "—"), 14, y); y += 5;
  doc.text("Horas trabajadas: " + (j.horas != null ? j.horas.toFixed(2) : "—"), 14, y); y += 5;
  doc.text("Ubicación inicio: " + fmtCoord(j.lat, j.lng), 14, y); y += 5;
  doc.text("Levantamientos registrados: " + levs.length, 14, y); y += 5;

  // Resumen ejecutivo: avance de objetivos con semáforo de color
  const avance = calcularAvanceObjetivos(j);
  if (avance.pct != null) {
    const nivelAvance = clasificarAvance(avance.pct);
    doc.setTextColor(...colorNivelRGB(nivelAvance));
    doc.text("Avance objetivos: " + avance.pct + "% (" + avance.hechosCheck + "/" + avance.totalCheck + " completados)", 14, y);
    doc.setTextColor(0, 0, 0);
    y += 5;
  }
  y += 5;

  // Objetivos del día: checklist con lo pendiente primero
  if (j.objetivos && j.objetivos.length) {
    doc.setFontSize(13);
    doc.text("Objetivos del día", 14, y); y += 6;
    j.objetivos.forEach((bloque) => {
      if (y > 250) { doc.addPage(); y = 16; }
      doc.setFontSize(11);
      doc.text(bloque.plantillaNombre, 14, y); y += 4;
      const itemsOrdenados = [...bloque.items].sort((a, b) => {
        const pa = estaPendienteObjetivo(a), pb = estaPendienteObjetivo(b);
        return pa === pb ? 0 : (pa ? -1 : 1);
      });
      doc.autoTable({
        startY: y,
        head: [["Ítem", "Estado / Valor", "Hora", "Nota"]],
        body: itemsOrdenados.map((it) => [
          it.texto,
          estadoObjetivoTexto(it),
          it.tipo === "check" && it.hora ? fmtHoraCorta(it.hora) : "—",
          it.nota || "—"
        ]),
        styles: { fontSize: 8 },
        headStyles: { fillColor: [232, 98, 44] },
        margin: { left: 14, right: 14 },
        didParseCell: (data) => {
          if (data.section === "body" && data.column.index === 1) {
            const it = itemsOrdenados[data.row.index];
            data.cell.styles.textColor = colorNivelRGB(estaPendienteObjetivo(it) ? "rojo" : "verde");
          }
        }
      });
      y = doc.lastAutoTable.finalY + 8;
    });
  }

  levs.forEach((l) => {
    const columnas = INSTRUMENTOS[l.instrumento].tipos[l.tipo].columnas;
    if (y > 260) { doc.addPage(); y = 16; }
    doc.setFontSize(13);
    doc.text(l.instrumentoNombre + " — " + l.tipoNombre, 14, y); y += 5;
    doc.setFontSize(9);
    doc.text("Equipo: " + (l.equipo || "—") + "  |  " + fmtHoraCorta(l.fechaInicio) + (l.fechaFin ? " – " + fmtHoraCorta(l.fechaFin) : ""), 14, y);
    y += 4;

    doc.autoTable({
      startY: y,
      head: [columnas.map((c) => c.label).concat(sesEsEstatico(l) ? ["Sesión"] : []).concat(["Hora", "Lat", "Lng"])],
      body: l.puntos.map((p) => columnas.map((c) => String(p.valores[c.key] ?? "")).concat(sesEsEstatico(l) ? [sesNombre(l, p)] : []).concat([
        fmtHoraCorta(p.timestamp), p.lat != null ? p.lat.toFixed(5) : "", p.lng != null ? p.lng.toFixed(5) : ""
      ])),
      styles: { fontSize: 8 },
      headStyles: { fillColor: [29, 92, 99] },
      margin: { left: 14, right: 14 }
    });
    y = doc.lastAutoTable.finalY + 10;
  });

  // Fotos requeridas por levantamiento
  for (const l of levs) {
    const frs = (l.fotosReq || []).filter((f) => f.foto);
    if (!frs.length) continue;
    doc.addPage();
    doc.setFontSize(12);
    doc.text("Fotos — " + l.instrumentoNombre + " · " + l.tipoNombre, 14, 16);
    let yy = 24;
    const cw = 88, ch = 78;
    for (let i = 0; i < frs.length; i++) {
      const col = i % 2;
      if (col === 0 && i > 0) yy += ch + 14;
      if (yy + ch + 10 > 285) { doc.addPage(); yy = 16; }
      const cx = 14 + col * (cw + 6);
      try {
        const dims = await imgDims(frs[i].foto);
        const sc = Math.min(cw / dims.w, ch / dims.h);
        const w = dims.w * sc, h = dims.h * sc;
        doc.addImage(frs[i].foto, formatoImagenJsPDF(frs[i].foto), cx + (cw - w) / 2, yy + (ch - h) / 2, w, h);
      } catch (err) { /* se omite */ }
      doc.setFontSize(8);
      doc.text(frs[i].nombre + " · " + fmtHoraCorta(frs[i].timestamp), cx, yy + ch + 4);
    }
  }

  // Páginas de fotos
  const puntosConFoto = levs.flatMap((l) => l.puntos.filter((p) => p.foto || (p.fotos && p.fotos.length)).map((p) => ({ l, p })));
  for (const { l, p } of puntosConFoto) {
    doc.addPage();
    if (esCatastro(l)) {
      const v = p.valores || {};
      doc.setFontSize(12);
      doc.text("Catastro — " + (v.codigo || "Elemento " + p.numero) + (v.tipoElemento ? " (" + v.tipoElemento + ")" : ""), 14, 16);
      doc.setFontSize(9);
      const lineas = [
        "Estado: " + catEstadoInfo(v.estado).t + "  |  " + fmtHoraCorta(p.timestamp) + "  |  " + fmtCoord(p.lat, p.lng) + (p.ubicFuente ? " (" + fmtFuenteUbic(p.ubicFuente).replace(/^\S+\s/, "") + ")" : ""),
        v.descripcion ? "Descripción: " + v.descripcion : "", v.atributos ? "Atributos: " + v.atributos : "", v.obs ? "Notas: " + v.obs : ""
      ].filter(Boolean);
      let yy = 22;
      lineas.forEach((t) => { const ws = doc.splitTextToSize(t, 182); doc.text(ws, 14, yy); yy += ws.length * 4.2; });
      yy += 3;
      const fotos = (p.fotos && p.fotos.length ? p.fotos : [{ dataUrl: p.foto, rol: "general" }]);
      const cw = 88, ch = 80;
      for (let i = 0; i < fotos.length; i++) {
        const col = i % 2, fila = Math.floor(i / 2);
        let cy = yy + fila * (ch + 8);
        if (cy + ch + 8 > 285) { doc.addPage(); yy = 16 - fila * (ch + 8); cy = yy + fila * (ch + 8); }
        const cx = 14 + col * (cw + 6);
        try {
          const dims = await imgDims(fotos[i].dataUrl);
          const sc = Math.min(cw / dims.w, ch / dims.h);
          const w = dims.w * sc, h = dims.h * sc;
          doc.addImage(fotos[i].dataUrl, formatoImagenJsPDF(fotos[i].dataUrl), cx + (cw - w) / 2, cy + (ch - h) / 2, w, h);
          doc.setFontSize(8);
          doc.text((CAT_ROLES.find((r) => r[0] === fotos[i].rol) || ["", "Foto"])[1], cx, cy + ch + 4);
        } catch (err) { /* si falla la imagen, se omite */ }
      }
      continue;
    }
    doc.setFontSize(12);
    doc.text(l.instrumentoNombre + " — Punto " + p.numero, 14, 16);
    doc.setFontSize(9);
    doc.text(fmtHoraCorta(p.timestamp) + " · " + fmtCoord(p.lat, p.lng), 14, 22);
    try {
      const dims = await imgDims(p.foto);
      const maxW = 180, maxH = 220;
      let w = dims.w, h = dims.h;
      const scale = Math.min(maxW / w, maxH / h, 1);
      w *= scale; h *= scale;
      doc.addImage(p.foto, formatoImagenJsPDF(p.foto), 14, 30, w, h);
    } catch (err) { /* si falla la imagen, se omite */ }
  }

  return doc;
}
function imgDims(dataUrl) {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.onload = () => resolve({ w: img.width, h: img.height });
    img.onerror = reject;
    img.src = dataUrl;
  });
}
